public AbstractModel MutableClone()
	{
		AbstractModel abstractModel = (AbstractModel)MemberwiseClone();
		abstractModel.IsMutable = true;
		abstractModel.DeepCloneFields();
		abstractModel.AfterCloned();
		return abstractModel;
	}

protected virtual void AfterCloned()
	{
		this.ExecutionFinished = null;
	}

public CardModel CreateCard(CardModel canonicalCard, Player owner)
	{
		CardModel cardModel = canonicalCard.ToMutable();
		AddCard(cardModel, owner);
		cardModel.AfterCreated();
		return cardModel;
	}

public CardModel CloneCard(CardModel mutableCard)
	{
		CardModel cardModel = (CardModel)mutableCard.ClonePreservingMutability();
		AddCard(cardModel);
		return cardModel;
	}

