using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
using HarmonyLib;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.CardPools;
using MegaCrit.Sts2.Core.Models.Enchantments;
using MegaCrit.Sts2.Core.Entities.Cards;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private static int TaskCreationSubscriberCount(AbstractModel source, Type owner, string field)
        => ((Delegate?)owner.GetField(field, BindingFlags.Instance | BindingFlags.NonPublic)!
            .GetValue(source))?.GetInvocationList().Length ?? 0;

    private static object TaskCreationMethod(MethodInfo method)
    {
        Patches? patches = Harmony.GetPatchInfo(method);
        return new { declaringType = method.DeclaringType!.FullName, signature = method.ToString(),
            method.Module.ModuleVersionId, token = method.MetadataToken,
            ilSha256 = Convert.ToHexString(SHA256.HashData(method.GetMethodBody()!.GetILAsByteArray()!)),
            patchCount = patches is null ? 0 : patches.Prefixes.Count + patches.Postfixes.Count
                + patches.Transpilers.Count + patches.Finalizers.Count };
    }

    private async Task RunTaskCardCreationAsync(CombatState live, Player player)
    {
        // These are detached, fixture-owned native models; injected callbacks
        // never write a root/live card. Attach before capturing the root.
        CardModel source = ModelDb.Card<Shiv>().ToMutable();source.Owner = player;
        CardCmd.Enchant<Inky>(source, 1);
        CardModel target = ModelDb.Card<DefendSilent>().ToMutable();
        int enchantmentCallbacks = 0, executionCallbacks = 0;
        source.EnchantmentChanged += () => { enchantmentCallbacks++;target.ExhaustOnNextPlay = true; };
        source.ExecutionFinished += _ => executionCallbacks++;
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        CombatPredictionSimulator parent = root.ForkSimulator();
        string Full(CombatPredictionSimulator sim) => ContinuationStamp.CapturePredicted(player, sim,
            ((SimulatedCombatState)sim.State.CombatState).GetPlayerTurnNumber(player), root.Forecast,
            root.StartTurnNumber).StateText + "\nHISTORY=" + CardContinuationContractHistoryText(sim);
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText, parentBefore = Full(parent);
        FieldInfo allCardsField = typeof(CombatState).GetField("_allCards", BindingFlags.Instance | BindingFlags.NonPublic)!;
        CardModel[] allCardsBefore = ((IEnumerable<CardModel>)allCardsField.GetValue(live)!).ToArray();

        CardModel native = (CardModel)source.MutableClone();
        if (enchantmentCallbacks != 1 || !target.ExhaustOnNextPlay || executionCallbacks != 0)
            throw new InvalidOperationException("Native clone did not expose its pre-cleanup copied callback.");
        int nativeCallbackCount = enchantmentCallbacks;
        target.ExhaustOnNextPlay = false;
        CardModel simulated;
        using (SimulationNotificationIsolation.Enter()) simulated = PredictionUtils.CloneCardStateForSimulation(source);
        if (enchantmentCallbacks != nativeCallbackCount || target.ExhaustOnNextPlay)
            throw new InvalidOperationException("Simulation clone leaked the source callback.");
        foreach (CardModel clone in new[] { native, simulated })
        {
            if (TaskCreationSubscriberCount(clone, typeof(CardModel), "EnchantmentChanged") != 0
                || TaskCreationSubscriberCount(clone, typeof(AbstractModel), "ExecutionFinished") != 0)
                throw new InvalidOperationException("Clone retained copied declared or inherited observers.");
            clone.InvokeExecutionFinished();
            if (!ReferenceEquals(clone.Enchantment!.Card, clone) || ReferenceEquals(clone.Enchantment, source.Enchantment))
                throw new InvalidOperationException("Cloned enchantment ownership was not isolated.");
        }
        if (executionCallbacks != 0 || TaskCreationSubscriberCount(source, typeof(AbstractModel), "ExecutionFinished") != 1)
            throw new InvalidOperationException("Inherited observer cleanup changed the source.");
        source.InvokeExecutionFinished();
        if (executionCallbacks != 1) throw new InvalidOperationException("Source inherited event no longer works.");

        var nativeState = parent.Fork();var simulatedState = parent.Fork();
        using (SimulationNotificationIsolation.Enter())
        {
            nativeState.AddToPile(PredictedCard.FromGenerated(native), PileType.Exhaust);
            simulatedState.AddToPile(PredictedCard.FromGenerated(simulated), PileType.Exhaust);
        }
        if (Full(nativeState) != Full(simulatedState))
            throw new InvalidOperationException("Final clone state differs after observer cleanup.");

        int nativeCreatedAct, simulatedCreatedAct, nativeCopiedAct, simulatedCopiedAct;
        CardModel? created = null, copied = null;
        try
        {
            created = live.CreateCard<SpoilsMap>(player);
            nativeCreatedAct = ((SpoilsMap)created).SpoilsActIndex;
            var predicted = PredictedCard.Create(ModelDb.Card<SpoilsMap>(), player);
            simulatedCreatedAct = ((SpoilsMap)predicted.Preview).SpoilsActIndex;
            copied = created.CreateClone();
            nativeCopiedAct = ((SpoilsMap)copied).SpoilsActIndex;
            var predictedCopy = PredictedCard.FromGenerated(created).CreateClone();
            simulatedCopiedAct = ((SpoilsMap)predictedCopy.Preview).SpoilsActIndex;
            if (nativeCreatedAct != 1 || simulatedCreatedAct != -1 || nativeCopiedAct != 1 || simulatedCopiedAct != 1)
                throw new InvalidOperationException("Creation versus gameplay-copy boundary was not reproduced.");
        }
        finally
        {
            if (copied is not null) live.RemoveCard(copied);
            if (created is not null) live.RemoveCard(created);
        }

        // Serial Fork ownership followed by parallel branch-local gameplay
        // copies, rather than simultaneous Fork of one mutable parent.
        string seededBefore = Full(simulatedState);
        var children = Enumerable.Range(0, 16).Select(_ => simulatedState.Fork()).ToArray();
        await Task.WhenAll(children.Select((child, index) => Task.Run(() =>
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            PredictedCard original = child.State.GetPlayerCombatState(player).ExhaustPile.Cards.Last();
            original.MutablePreview.ExhaustOnNextPlay = true;
            PredictedCard clone = original.CreateClone();
            clone.MutablePreview.Enchantment!.Amount = index + 2;
            child.AddToPile(clone, PileType.Exhaust);
            if (clone.Preview.ExhaustOnNextPlay || clone.Preview.Enchantment!.Amount != index + 2
                || !ReferenceEquals(clone.Preview.Enchantment!.Card, clone.Preview)
                || original.Preview.Enchantment!.Amount != 1
                || TaskCreationSubscriberCount(clone.Preview, typeof(AbstractModel), "ExecutionFinished") != 0)
                throw new InvalidOperationException("Branch-local gameplay copy leaked or failed native reset rules.");
        })));
        for (int index = 0; index < children.Length; index++)
        {
            var pile = children[index].State.GetPlayerCombatState(player).ExhaustPile;
            if (pile.Cards.Last().Preview.Enchantment!.Amount != index + 2)
                throw new InvalidOperationException("Sibling copy mutation leaked.");
            var grandchild = children[index].Fork();
            if (Full(grandchild) != Full(children[index]))
                throw new InvalidOperationException("Gameplay copy did not preserve its full state/history/RNG through Fork.");
        }
        CardModel[] allCardsAfter = ((IEnumerable<CardModel>)allCardsField.GetValue(live)!).ToArray();
        if (!allCardsBefore.SequenceEqual(allCardsAfter, ReferenceEqualityComparer.Instance)
            || liveBefore != ContinuationStamp.CaptureLive(live).StateText || parentBefore != Full(parent)
            || seededBefore != Full(simulatedState))
            throw new InvalidOperationException("Creation contract changed parent/live or the native floating-card registry.");
        CardModel[] unlockedColorless = ModelDb.CardPool<ColorlessCardPool>()
            .GetUnlockedCards(player.UnlockState, player.RunState.CardMultiplayerConstraint).ToArray();
        var creationSources = allCardsBefore.Select(card => card.GetType()).Append(typeof(Shiv))
            .Append(typeof(FranticEscape)).Distinct().OrderBy(type => type.FullName, StringComparer.Ordinal)
            .Select(type => new { type = type.FullName, afterCreated = TaskCreationMethod(type.GetMethod("AfterCreated")!) })
            .ToArray();
        var methods = new[]
        {
            typeof(AbstractModel).GetMethod("MutableClone")!,
            typeof(AbstractModel).GetMethod("AfterCloned", BindingFlags.Instance | BindingFlags.NonPublic)!,
            typeof(CardModel).GetMethod("DeepCloneFields", BindingFlags.Instance | BindingFlags.NonPublic)!,
            typeof(CardModel).GetMethod("AfterCloned", BindingFlags.Instance | BindingFlags.NonPublic)!,
            typeof(CardModel).GetMethod("AfterCreated")!, typeof(SpoilsMap).GetMethod("AfterCreated")!,
            typeof(CombatState).GetMethod("CreateCard", new[] { typeof(CardModel), typeof(Player) })!,
            typeof(CombatState).GetMethod("CloneCard")!, typeof(CardModel).GetMethod("CreateClone")!,
        }.Select(TaskCreationMethod).ToArray();
        _completedChecks.Add("CardCreation:NativePreCleanupCallbackCounterexample:InheritedObserverCleared:FinalClonedFullStateEqual:NativeCreatedSpoilsMapDiffers:NativeAndSimGameplayCopyPreserveCreatedState:SixteenBranchGameplayCopiesTwoGenerationFork:FullHistoryNineRngFloatingParentLiveIsolation");
        _completedChecks.Add("TASK_CARD_CREATION " + JsonSerializer.Serialize(new { nativeCallbackCount,
            simulationAdditionalCallbacks = enchantmentCallbacks - nativeCallbackCount, executionCallbacks,
            nativeCreatedAct, simulatedCreatedAct, nativeCopiedAct, simulatedCopiedAct, methods, creationSources,
            spoilsCanBeGeneratedInCombat = ModelDb.Card<SpoilsMap>().CanBeGeneratedInCombat,
            spoilsRarity = ModelDb.Card<SpoilsMap>().Rarity.ToString(),
            unlockedColorlessCount = unlockedColorless.Length,
            spoilsInUnlockedColorless = unlockedColorless.Any(card => card is SpoilsMap),
            initialSourceHasSpoils = allCardsBefore.Any(card => card is SpoilsMap),
            forkCount = children.Length, wholeRootCertified = false, actualPrunes = 0 }));
    }
}

